The C++ program below implements binary search over a sorted vector. It currently fails to locate existing target values because the search bounds updates are inverted. Fix the bug so target values are located correctly.

Buggy program:
```cpp
#include <iostream>
#include <vector>
using namespace std;

bool searchValue(const vector<int>& values, int target) {
    int left = 0;
    int right = values.size() - 1;

    while (left <= right) {
        int mid = (left + right) / 2;

        if (values[mid] == target)
            return true;

        if (target < values[mid])
            left = mid + 1;
        else
            right = mid - 1;
    }

    return false;
}

int main() {
    vector<int> values = {1, 3, 5, 7, 9};
    vector<int> queries = {7, 2, 9};

    for (int target : queries)
        cout << (searchValue(values, target) ? "FOUND" : "NOT FOUND") << "\n";
}
```

