task:
Maintain connected components using union-find. CONNECTED must determine whether two nodes belong to the same component. SIZE must return the number of nodes in the component containing the requested node.

Buggy program:
```cpp
#include <iostream>
#include <vector>
#include <numeric>
#include <string>
using namespace std;

class DSU {
    vector<int> parent, sz;

public:
    DSU(int n) : parent(n), sz(n, 1) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {
        return parent[x] == x ? x : parent[x] = find(parent[x]);
    }

    void unite(int a, int b) {
        a = find(a);
        b = find(b);

        if (a == b) return;

        if (sz[a] < sz[b]) swap(a, b);

        parent[b] = a;
        sz[b] += sz[a];
    }

    bool connected(int a, int b) {
        return find(a) == find(b);
    }

    int size(int x) {
        return sz[find(x)];
    }
};

int main() {
    int n, operations;
    cin >> n >> operations;

    DSU dsu(n);

    while (operations--) {
        string command;
        cin >> command;

        if (command == "UNION") {
            int a, b;
            cin >> a >> b;
            dsu.unite(a, b);
        } else if (command == "CONNECTED") {
            int a, b;
            cin >> a >> b;
            cout << (dsu.connected(a, b) ? "YES" : "NO") << "\n";
        } else if (command == "SIZE") {
            int x;
            cin >> x;
            cout << dsu.size(x) << "\n";
        }
    }
}
```

