task:
Group events into sessions independently for each user. Consecutive events from the same user belong to the same session when their time gap is at most 30 seconds. Print sessions sorted by user and then by start time.

Buggy program:
```javascript
const fs = require("fs");

const lines = fs.readFileSync(0, "utf8").trim().split("\n");
const n = Number(lines[0]);
const sessions = [];
let current = null;

for (let i = 1; i <= n; i++) {
    const [user, timeText] = lines[i].trim().split(/\s+/);
    const time = Number(timeText);

    if (!current || current.user !== user || time - current.end > 30) {
        current = { user, start: time, end: time, count: 1 };
        sessions.push(current);
    } else {
        current.end = time;
        current.count++;
    }
}

sessions.sort((a, b) =>
    a.user.localeCompare(b.user) || a.start - b.start
);

for (const s of sessions) {
    console.log(`${s.user} ${s.start} ${s.end} ${s.count}`);
}
```

