task:
The C++ program below implements a segment tree supporting range addition and range sum queries with lazy propagation. It currently forgets to push down lazy values to children during range updates and queries, returning corrupted sums. Fix the bug so the segment tree accurately computes range sums.

Buggy program:
```cpp
#include <iostream>
#include <vector>
using namespace std;

class LazySegTree {
    int n;
    vector<long long> tree, lazy;
public:
    LazySegTree(int size) : n(size), tree(4 * size, 0), lazy(4 * size, 0) {}

    void push(int node, int l, int r) {
        if (lazy[node] != 0 && l != r) {
            lazy[2 * node] += lazy[node];
            lazy[2 * node + 1] += lazy[node];
            lazy[node] = 0;
        }
    }

    void updateRange(int node, int l, int r, int ql, int qr, long long val) {
        if (ql <= l && r <= qr) {
            tree[node] += (r - l + 1) * val;
            lazy[node] += val;
            return;
        }
        int mid = (l + r) / 2;
        if (ql <= mid) updateRange(2 * node, l, mid, ql, qr, val);
        if (qr > mid) updateRange(2 * node + 1, mid + 1, r, ql, qr, val);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

    long long queryRange(int node, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) return tree[node];
        int mid = (l + r) / 2;
        long long sum = 0;
        if (ql <= mid) sum += queryRange(2 * node, l, mid, ql, qr);
        if (qr > mid) sum += queryRange(2 * node + 1, mid + 1, r, ql, qr);
        return sum;
    }
};

int main() {
    LazySegTree st(5);
    st.updateRange(1, 0, 4, 0, 2, 5); // [5, 5, 5, 0, 0]
    cout << st.queryRange(1, 0, 4, 1, 3) << "\n";
    st.updateRange(1, 0, 4, 2, 4, 3); // [5, 5, 8, 3, 3]
    cout << st.queryRange(1, 0, 4, 0, 4) << "\n";
}
```

