The C++ program below implements child node splitting in a 2-3 B-Tree (max keys = 2). When splitting full child nodes, parent key insertion fails to shift subsequent child pointers, resulting in orphaned subtrees. Fix the bug so the B-Tree maintains proper multiway search tree invariants.

Buggy program:
```cpp
#include <iostream>
#include <vector>
using namespace std;

struct BNode {
    vector<int> keys;
    vector<BNode*> children;
    bool isLeaf;
    BNode(bool leaf) : isLeaf(leaf) {}
};

class BTree {
public:
    BNode* root;
    BTree() { root = new BNode(true); }

    void splitChild(BNode* parent, int i, BNode* fullChild) {
        BNode* newChild = new BNode(fullChild->isLeaf);
        int midKey = fullChild->keys[1];
        newChild->keys.push_back(fullChild->keys[2]);
        fullChild->keys.resize(1);

        if (!fullChild->isLeaf) {
            newChild->children.push_back(fullChild->children[2]);
            newChild->children.push_back(fullChild->children[3]);
            fullChild->children.resize(2);
        }

        parent->keys.insert(parent->keys.begin() + i, midKey);
        // BUG: Fails to insert newChild at children[i + 1]
    }

    void traverse(BNode* node) {
        if (!node) return;
        for (size_t i = 0; i < node->keys.size(); i++) {
            if (!node->isLeaf && i < node->children.size()) traverse(node->children[i]);
            cout << node->keys[i] << " ";
        }
        if (!node->isLeaf && node->children.size() > node->keys.size())
            traverse(node->children.back());
    }
};

int main() {
    BTree tree;
    BNode* r = tree.root;
    r->keys = {10, 20, 30};
    BNode* newRoot = new BNode(false);
    newRoot->children.push_back(r);
    tree.splitChild(newRoot, 0, r);
    tree.root = newRoot;
    tree.traverse(tree.root);
    cout << "\n";
}
